-- Planches du lot 1, validées le 05/11/2026 : eau de riz, cendres, feuilles mortes,
-- ail au pied des rosiers, coquilles au pied, marc de café (lib/secrets/planches/lot1.ts).
-- Données seulement ; une planche déjà posée ou retouchée n’est pas touchée.
UPDATE "garden_tips" AS t SET "planche" = v.planche, "updatedAt" = now()
FROM (VALUES
  ('coquilles-pied', '{"panels":[{"art":"coquilles-pied/1","caption":"Fais sécher les coquilles quelques jours, puis broie-les le plus fin possible.","emphasis":"broie-les le plus fin possible"},{"art":"coquilles-pied/2","caption":"Ajoute la poudre au compost, ou griffe-la en surface au pied de la plante.","emphasis":"griffe-la en surface"},{"art":"coquilles-pied/3","caption":"Contre le cul noir des tomates, la vraie parade : un arrosage régulier, sans à-coups.","emphasis":"un arrosage régulier, sans à-coups"}],"caution":{"art":"coquilles-pied/caution","title":"Un effet lent et modeste.","text":"Le cul noir vient d’un arrosage irrégulier bien plus que d’un manque de calcium dans le sol.","tone":"note"}}'::jsonb),
  ('ail-rosier', '{"panels":[{"art":"ail-rosier/1","caption":"Choisis 4 ou 5 gousses d’ail bien fermes.","emphasis":"4 ou 5 gousses d’ail"},{"art":"ail-rosier/2","caption":"Plante-les pointe en haut, à 3 cm de profondeur, à 20 cm du pied du rosier.","emphasis":"pointe en haut"},{"art":"ail-rosier/3","caption":"Laisse-les pousser : coupe les tiges au printemps pour la cuisine.","emphasis":"coupe les tiges au printemps"}],"caution":{"art":"ail-rosier/caution","title":"Aucun effet démontré.","text":"Contre les maladies, rien ne l’a prouvé : c’est une tradition, et une récolte en prime.","tone":"note"}}'::jsonb),
  ('marc-cafe', '{"panels":[{"art":"marc-cafe/1","caption":"Fais sécher le marc sur une assiette quelques jours.","emphasis":"sécher le marc"},{"art":"marc-cafe/2","caption":"Mélange-le au compost, ou griffe une fine couche dans la terre au pied de la plante.","emphasis":"une fine couche"},{"art":"marc-cafe/3","caption":"Une poignée par mois suffit.","emphasis":"Une poignée par mois"}],"caution":{"art":"marc-cafe/caution","title":"Jamais sur des semis.","text":"Ni en couche épaisse posée sur le sol : il se tasse, moisit, et freine la germination.","tone":"warning"}}'::jsonb),
  ('cendres', '{"panels":[{"art":"cendres/1","caption":"Attends que les cendres soient parfaitement froides, plusieurs jours.","emphasis":"parfaitement froides"},{"art":"cendres/2","caption":"Tamise-les pour retirer les morceaux de charbon.","emphasis":"Tamise-les"},{"art":"cendres/3","caption":"Répands sur la terre une fine couche : une poignée par mètre carré, une fois par an.","emphasis":"une poignée par mètre carré"}],"caution":{"art":"cendres/caution","title":"Pas partout, et du bois non traité seulement.","text":"Jamais sur les plantes de terre de bruyère ni sur un sol déjà calcaire. Ni charbon de barbecue, ni bois peint ou aggloméré.","tone":"warning"}}'::jsonb),
  ('eau-riz', '{"panels":[{"art":"eau-riz/1","caption":"Rince ton riz une fois, et garde cette première eau.","emphasis":"garde cette première eau"},{"art":"eau-riz/2","caption":"Arrose ta plante avec, à la place d’un arrosage ordinaire.","emphasis":"à la place d’un arrosage ordinaire"},{"art":"eau-riz/3","caption":"Une fois par mois suffit.","emphasis":"Une fois par mois"}],"caution":{"art":"eau-riz/caution","title":"Seulement sur un terreau qui sèche bien.","text":"L’amidon peut faire moisir une terre qui reste humide entre deux arrosages.","tone":"warning"}}'::jsonb),
  ('feuilles-mortes', '{"panels":[{"art":"feuilles-mortes/1","caption":"Ramasse les feuilles mortes saines.","emphasis":"saines"},{"art":"feuilles-mortes/2","caption":"Étale-les en couche de 5 à 10 cm au pied des massifs et des arbustes.","emphasis":"5 à 10 cm"},{"art":"feuilles-mortes/3","caption":"Le surplus va en tas ou dans un sac percé : dans un an, tu auras du terreau.","emphasis":"dans un an, tu auras du terreau"}],"caution":{"art":"feuilles-mortes/caution","title":"Écarte les feuilles malades.","text":"Comme celles des rosiers tachés de noir : la maladie y passe l’hiver.","tone":"warning"}}'::jsonb)
) AS v(slug, planche)
WHERE t."slug" = v.slug AND t."planche" IS NULL;
